script:
// IMPORTANT: root_element est fourni par l'environnement Frappe Custom Block
// Nous utilisons $(function() { ... }) qui est un raccourci pour $(document).ready(function() { ... })
// pour s'assurer que le DOM est chargé avant d'interagir avec.
$(function() {
    // Vérification initiale pour s'assurer que root_element est défini
    if (!root_element) {
        console.error("Erreur: 'root_element' n'est pas défini. Le script n'est peut-être pas exécuté dans le contexte attendu d'un Custom HTML Block.");
        frappe.show_alert({ message: "Erreur d'initialisation du widget. Contactez l'administrateur.", indicator: 'red' });
        return; // Arrêter l'exécution du script
    }

    // Cibler le conteneur principal du widget à l'intérieur du root_element fourni.
    const widgetContainer = root_element.querySelector('#resume_ai_widget_container');

    // Vérification si le conteneur principal a été trouvé
    if (!widgetContainer) {
        console.error("Erreur: Le conteneur '#resume_ai_widget_container' n'a pas été trouvé à l'intérieur de root_element.");
        frappe.show_alert({ message: "Erreur: Conteneur du widget introuvable.", indicator: 'red' });
        return; // Arrêter l'exécution du script
    }

    let currentDocName = null; // Pour gérer le document existant sélectionné
    let fileUploader = null;   // Référence au contrôle de téléchargement de fichier

    // --- Section pour la sélection de document existant ---
    const existingDocLinkField = widgetContainer.querySelector('#existing_doc_link_field');
    const docSelector = frappe.ui.form.make_control({
        parent: existingDocLinkField,
        df: {
            fieldtype: 'Link',
            fieldname: 'document',
            options: 'resume_document_ai',
            label: 'Document',
            get_query: function() {
                return { filters: {} };
            },
            on_change: function() {
                currentDocName = docSelector.get_value();
                if (currentDocName) {
                    $(widgetContainer).find('#summarize_button_existing').show();
                    $(widgetContainer).find('#new_file_upload_field input[type="file"]').prop('disabled', true);
                    $(widgetContainer).find('#summary_output').show();
                    loadDocumentDetails(currentDocName);
                } else {
                    $(widgetContainer).find('#summarize_button_existing').hide();
                    $(widgetContainer).find('#new_file_upload_field input[type="file"]').prop('disabled', false);
                    $(widgetContainer).find('#summary_output').empty().hide();
                    $(widgetContainer).find('#widget_status').empty();
                }
            }
        },
        render_input: true
    });

    // --- Section pour le téléchargement de nouveau fichier ---
    const newFileUploadField = widgetContainer.querySelector('#new_file_upload_field');
    fileUploader = frappe.ui.form.make_control({
        parent: newFileUploadField,
        df: {
            fieldtype: 'Attach',
            fieldname: 'pdf_file',
            label: 'Sélectionner un fichier PDF',
            options: 'PDF',
            on_upload_complete: function(attachment) {
                $(docSelector.wrapper).find('input').prop('disabled', true);

                frappe.show_alert({ message: "Fichier PDF téléchargé. Lancement du résumé…", indicator: 'blue', delay: 5 });
                $(widgetContainer).find('#summarize_button_existing').hide();
                $(widgetContainer).find('#summary_output').empty().show();
                updateWidgetStatus("En traitement - Téléchargement...");

                frappe.call({
                    method: 'resume_ai.api.process_uploaded_pdf',
                    args: {
                        file_docname: attachment.name,
                        file_url: attachment.file_url,
                        original_filename: attachment.file_name
                    },
                    freeze: true,
                    freeze_message: "L’IA travaille sur le résumé du nouveau document…",
                    callback(r) {
                        if (!r.exc) {
                            frappe.show_alert({ message: "Nouveau document résumé avec succès !", indicator: 'green' });
                            $(widgetContainer).find('#summary_output').html(`
                                <h5>Nouveau document créé : <a href="/app/resume-document-ai/${r.message.docname}" target="_blank">${r.message.docname}</a></h5>
                                <h6>Résumé :</h6>
                                <p class="widget-summary-content">${r.message.resume}</p>
                            `).show();
                            updateWidgetStatus("Fini");
                            fileUploader.set_value(null);
                            $(docSelector.wrapper).find('input').prop('disabled', false);
                        } else {
                            frappe.show_alert({ message: `Erreur lors du traitement du nouveau fichier: ${r.exc}`, indicator: 'red' });
                            console.error("Erreur API:", r.exc);
                            updateWidgetStatus("Erreur");
                            $(docSelector.wrapper).find('input').prop('disabled', false);
                        }
                    },
                    error: function(xhr, textStatus, errorThrown) {
                        frappe.show_alert({ message: `Erreur de connexion lors du traitement du fichier: ${textStatus}`, indicator: 'red' });
                        console.error("Erreur AJAX:", textStatus, errorThrown);
                        updateWidgetStatus("Erreur de connexion");
                        $(docSelector.wrapper).find('input').prop('disabled', false);
                    }
                });
            }
        },
        render_input: true
    });

    // Fonctions auxiliaires
    function loadDocumentDetails(docname) {
        frappe.db.get_doc('resume_document_ai', docname).then(doc => {
            if (doc) {
                $(widgetContainer).find('#summary_output').html(`
                    <h5>Statut actuel : <span class="widget-status-text">${doc.status || 'N/A'}</span></h5>
                    ${doc.resume ? `<h6>Résumé :</h6><p class="widget-summary-content">${doc.resume}</p>` : '<p>Aucun résumé disponible.</p>'}
                `).show();
                updateWidgetStatus(doc.status);
            }
        }).catch(error => {
            console.error("Erreur lors du chargement du document :", error);
            frappe.show_alert({ message: "Erreur lors du chargement du document.", indicator: 'red' });
            $(widgetContainer).find('#summary_output').empty().hide();
            $(widgetContainer).find('#widget_status').empty();
        });
    }

    function updateWidgetStatus(status) {
        let statusMessage = '';
        let statusClass = '';

        // S'assurer que 'status' est une chaîne de caractères pour utiliser startsWith
        const safeStatus = String(status || '').trim(); 

        if (safeStatus === "Fini") {
            statusMessage = "Résumé prêt ✅";
            statusClass = "status-green";
        } else if (safeStatus.startsWith("En traitement")) {
            statusMessage = "Résumé en cours… ⏳";
            statusClass = "status-orange";
        } else if (safeStatus === "Texte extrait") {
            statusMessage = "Texte extrait, en attente de résumé…";
            statusClass = "status-blue";
        } else if (safeStatus.startsWith("Erreur")) {
            statusMessage = "Erreur lors du résumé ❌";
            statusClass = "status-red";
        } else {
            statusMessage = "Prêt à commencer.";
            statusClass = "status-gray";
        }
        $(widgetContainer).find('#widget_status').html(`<span class="${statusClass}">${statusMessage}</span>`);
    }

    // Gérer le clic sur le bouton "Extraire et Résumer" pour les documents existants
    $(widgetContainer).on('click', '#summarize_button_existing', function() {
        if (!currentDocName) {
            frappe.show_alert({ message: "Veuillez sélectionner un document existant.", indicator: 'orange' });
            return;
        }

        frappe.show_alert({ message: "Relancement du résumé pour le document existant…", indicator: 'blue', delay: 3 });
        updateWidgetStatus("En traitement");
        $(widgetContainer).find('#summary_output').show();
        $(widgetContainer).find('#new_file_upload_field input[type="file"]').prop('disabled', true);

        frappe.call({
            method: 'resume_ai.api.extraire_et_resumer',
            args: { docname: currentDocName },
            freeze: true,
            freeze_message: "L’IA travaille sur le résumé…",
            callback(r) {
                if (!r.exc) {
                    frappe.show_alert({ message: "Résumé généré avec succès !", indicator: 'green' });
                    loadDocumentDetails(currentDocName);
                } else {
                    frappe.show_alert({ message: `Erreur: ${r.exc}`, indicator: 'red' });
                    console.error("Erreur de l'API :", r.exc);
                    updateWidgetStatus("Erreur");
                }
                $(widgetContainer).find('#new_file_upload_field input[type="file"]').prop('disabled', false);
            },
            error: function(xhr, textStatus, errorThrown) {
                frappe.show_alert({ message: `Erreur de connexion: ${textStatus}`, indicator: 'red' });
                console.error("Erreur AJAX :", textStatus, errorThrown);
                updateWidgetStatus("Erreur de connexion");
                $(widgetContainer).find('#new_file_upload_field input[type="file"]').prop('disabled', false);
            }
        });
    });

    // Initialiser le statut au chargement
    updateWidgetStatus();
});

