script:
function loadAgendaWidget(root_element) {
  const container = root_element.querySelector('#agenda-events');
  const monthEl = root_element.querySelector('#agenda-month');
  const dayEl = root_element.querySelector('#agenda-day');

  if (!container || !monthEl || !dayEl) return;

  const now = new Date();
  const months = ['JANV', 'FÉVR', 'MARS', 'AVRIL', 'MAI', 'JUIN', 'JUIL', 'AOÛT', 'SEPT', 'OCT', 'NOV', 'DÉC'];
  monthEl.textContent = months[now.getMonth()];
  dayEl.textContent = now.getDate();

  frappe.call({
    method: 'frappe.event.get_list',
    args: {
      doctype: 'Event',
      fields: ['subject', 'starts_on', 'ends_on', 'color'],
      filters: {
        starts_on: ['>=', frappe.datetime.now_date()]
      },
      order_by: 'starts_on asc',
      limit_page_length: 4
    },
    callback: function (r) {
      container.innerHTML = '';

      if (!r.message || r.message.length === 0) {
        container.innerHTML = '<p>Aucun événement à venir.</p>';
        return;
      }

      r.message.forEach(event => {
        const start = frappe.datetime.str_to_user(event.starts_on).split(' ')[1]?.slice(0, 5) || '—';
        const end = frappe.datetime.str_to_user(event.ends_on).split(' ')[1]?.slice(0, 5) || '—';
        const color = event.color || '#ececec';

        const div = document.createElement('div');
        div.className = 'event';
        div.style.backgroundColor = color;
        div.style.color = '#fff';
        div.innerHTML = `<strong>${event.subject}</strong><br><span>${start} – ${end}</span>`;
        container.appendChild(div);
      });
    }
  });
}

// Appel initial avec un élément racine (ex. document si global)
loadAgendaWidget(document);

